test-code.code:
import net.jcip.annotations.GuardedBy

class Bad1 {
    private val lock = Any()

    @GuardedBy("lock")
    var txt: String = ""

    fun setText(t: String) { txt = t } // bad
}

import net.jcip.annotations.GuardedBy

class Bad2 {
    private val lock = Any()

    @GuardedBy("lock")
    var txt: String = ""

    fun getText(): String { return txt } // bad
}

import net.jcip.annotations.GuardedBy

class Bad3 {
    private val lock1 = Any()
    private val lock2 = Any()

    @GuardedBy("lock1")
    var txt: String = ""

    fun setText(t: String) {
        synchronized(lock2) {
            txt = t // bad - wrong lock
        }
    }
}

import net.jcip.annotations.GuardedBy

class Bad4 {
    private val lock = Any()

    @GuardedBy("lock")
    var txt: String = ""

    @Synchronized fun setText(t: String) { txt = t } // bad - @Synchronized uses "this", not "lock"
}

import net.jcip.annotations.GuardedBy

class Bad5 {
    @GuardedBy("nonExistent")
    var txt: String = ""

    fun setText(t: String) { txt = t } // bad - no matching lock field
}

import net.jcip.annotations.GuardedBy

class Good1 {
    private val lock = Any()

    @GuardedBy("lock")
    var txt: String = ""

    fun getText(): String {
        return synchronized(lock) { txt } // good
    }
    fun setText(t: String) {
        synchronized(lock) { txt = t }    // good
    }
}

import net.jcip.annotations.GuardedBy

class Good2 {
    @GuardedBy("this")
    var txt: String = ""

    fun setText(t: String) { txt = t } // not this rule's concern
}

import net.jcip.annotations.GuardedBy
import org.springframework.beans.factory.annotation.Autowired

class Good3 {
    private val lock = Any()

    @GuardedBy("lock")
    var txt: String = ""

    @Autowired
    fun init(t: String) { txt = t } // good - framework injection
}

import net.jcip.annotations.GuardedBy

class Good4 {
    companion object {
        private val lock = Any()

        @GuardedBy("lock")
        var shared: String = ""
    }

    fun setShared(t: String) {
        synchronized(lock) { shared = t } // good
    }
}
